function validate(input) {
  const [{ Transactions = [] }] = input;
  const ids = new Set(), days = new Set();
  for (const [id, customer, date, amount] of Transactions) {
    if (id === null || customer === null || date === null || amount === null) return 'Transactions cannot hold nulls.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(date))) return `${date} is not a date.`;
    const key = `${customer}|${date}`;
    if (days.has(key)) return `Customer ${customer} has two transactions on ${date}.`;
    days.add(key);
    if (amount <= 0) return 'amount must be positive.';
  }
  return null;
}

