function generate(rand, size) {
  const small = size === 'small';
  const origin = small ? Date.UTC(2023, 3, 27) : Date.UTC(2023, 11, 1);
  const day = n => new Date(origin + n * 86400000).toISOString().slice(0, 10);
  const rows = [], used = new Set();
  if (small) {
    const customers = 1 + Math.floor(rand() * 4), want = Math.floor(rand() * 9);
    for (let tries = 0; rows.length < want && tries < 60; tries++) {
      const c = 101 + Math.floor(rand() * customers), d = Math.floor(rand() * 7);
      if (used.has(`${c}|${d}`)) continue;
      used.add(`${c}|${d}`);
      rows.push([c, day(d)]);
    }
  } else {
    for (let c = 0; c < 40; c++) {
      const density = 0.5 + rand() * 0.45;
      for (let d = 0; d < 60 && rows.length < 2000; d++) if (rand() < density) rows.push([1000 + c, day(d)]);
    }
  }
  // Shuffle so that transaction ids say nothing about the dates.
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  const Transactions = rows.map(([c, d], i) => [i + 1, c, d, 10 * (1 + Math.floor(rand() * 30))]);
  return [{ Transactions }];
}
